window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["lovable"]={html:"<div class=\"own-lovable\">\n  <header class=\"lv-nav\">\n    <a class=\"lv-brand\" href=\"#\" aria-label=\"Northwind home\">\n      <span class=\"lv-mark\" aria-hidden=\"true\">N</span>\n      <span class=\"lv-word\">Northwind</span>\n    </a>\n    <nav class=\"lv-links\" aria-label=\"Primary\">\n      <a href=\"#templates\">Templates</a>\n      <a href=\"#features\">Product</a>\n      <a href=\"#stats\">Customers</a>\n      <a href=\"#cta\">Pricing</a>\n    </nav>\n    <div class=\"lv-actions\">\n      <a class=\"lv-btn lv-btn-ghost\" href=\"#\">Log in</a>\n      <a class=\"lv-btn lv-btn-dark\" href=\"#cta\">Start building</a>\n      <button class=\"lv-menu\" type=\"button\" aria-label=\"Menu\" data-menu>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <section class=\"lv-hero\" aria-labelledby=\"lvHeroH\">\n    <div class=\"lv-wash\" aria-hidden=\"true\"></div>\n    <div class=\"lv-hero-inner\">\n      <span class=\"lv-eyebrow\">Northwind &middot; operations analytics</span>\n      <h1 id=\"lvHeroH\" class=\"lv-h1\">Build the dashboard<br>your operation deserves.</h1>\n      <p class=\"lv-sub\">Describe the dashboard you need and Northwind assembles the regions, throughput\n        and pricing views for you. Cream-smooth, no cold templates, no blank canvas.</p>\n\n      <form class=\"lv-chat\" data-chat aria-label=\"Describe a dashboard\">\n        <label class=\"lv-sr\" for=\"lvPrompt\">Describe your dashboard</label>\n        <textarea id=\"lvPrompt\" rows=\"1\" placeholder=\"A throughput board for our Nordic warehouses, week over week…\"></textarea>\n        <div class=\"lv-chat-foot\">\n          <div class=\"lv-suggest\" role=\"group\" aria-label=\"Suggestions\">\n            <button type=\"button\" class=\"lv-pill\" data-suggest>Weekly throughput board</button>\n            <button type=\"button\" class=\"lv-pill\" data-suggest>Regional pricing report</button>\n            <button type=\"button\" class=\"lv-pill\" data-suggest>Warehouse health digest</button>\n          </div>\n          <button type=\"submit\" class=\"lv-send\" aria-label=\"Generate\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>\n          </button>\n        </div>\n      </form>\n      <p class=\"lv-trust\">Trusted by 40,000 operations teams &middot; No credit card</p>\n    </div>\n  </section>\n\n  <section id=\"templates\" class=\"lv-sec\" aria-labelledby=\"lvTemplH\">\n    <div class=\"lv-wrap\">\n      <div class=\"lv-sec-head\">\n        <h2 id=\"lvTemplH\" class=\"lv-h2\">Start from a template.</h2>\n        <p class=\"lv-lead\">Every Northwind workspace ships with a gallery of operational templates &mdash;\n          throughput, region, pricing &mdash; ready to open and edit.</p>\n      </div>\n      <div class=\"lv-gallery\">\n        <a class=\"lv-card\" href=\"#\">\n          <div class=\"lv-thumb lv-thumb-a\" aria-hidden=\"true\">\n            <span class=\"lv-tile\"></span><span class=\"lv-tile\"></span><span class=\"lv-tile\"></span><span class=\"lv-tile\"></span>\n            <span class=\"lv-thumb-label\">Throughput</span>\n          </div>\n          <div class=\"lv-card-body\">\n            <h3 class=\"lv-card-title\">Warehouse throughput board</h3>\n            <p class=\"lv-card-desc\">Lines, docks and cycle time across every region.</p>\n            <span class=\"lv-cat\">Operations</span>\n          </div>\n        </a>\n        <a class=\"lv-card\" href=\"#\">\n          <div class=\"lv-thumb lv-thumb-b\" aria-hidden=\"true\">\n            <span class=\"lv-ring\"></span><span class=\"lv-ring\"></span>\n            <span class=\"lv-thumb-label\">Regions</span>\n          </div>\n          <div class=\"lv-card-body\">\n            <h3 class=\"lv-card-title\">Regional pricing report</h3>\n            <p class=\"lv-card-desc\">Margin, discount and tier mix by territory.</p>\n            <span class=\"lv-cat\">Finance</span>\n          </div>\n        </a>\n        <a class=\"lv-card\" href=\"#\">\n          <div class=\"lv-thumb lv-thumb-c\" aria-hidden=\"true\">\n            <span class=\"lv-bars\"><i style=\"--h:42%\"></i><i style=\"--h:68%\"></i><i style=\"--h:54%\"></i><i style=\"--h:86%\"></i><i style=\"--h:73%\"></i><i style=\"--h:95%\"></i></span>\n            <span class=\"lv-thumb-label\">Health</span>\n          </div>\n          <div class=\"lv-card-body\">\n            <h3 class=\"lv-card-title\">Warehouse health digest</h3>\n            <p class=\"lv-card-desc\">A weekly summary for the ops leadership team.</p>\n            <span class=\"lv-cat\">Leadership</span>\n          </div>\n        </a>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"stats\" class=\"lv-sec lv-sec-tight\" aria-labelledby=\"lvStatsH\">\n    <div class=\"lv-wrap\">\n      <h2 id=\"lvStatsH\" class=\"lv-sr\">Northwind at a glance</h2>\n      <div class=\"lv-stats\">\n        <div class=\"lv-stat\"><b>40M+</b><span>Rows modelled every day</span></div>\n        <div class=\"lv-stat\"><b>190+</b><span>Regions and territories</span></div>\n        <div class=\"lv-stat\"><b>98%</b><span>On-time reporting rate</span></div>\n        <div class=\"lv-stat\"><b>12 min</b><span>Median time to first board</span></div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"features\" class=\"lv-sec\" aria-labelledby=\"lvFeatH\">\n    <div class=\"lv-wrap\">\n      <div class=\"lv-sec-head lv-left\">\n        <h2 id=\"lvFeatH\" class=\"lv-h2\">Warm, careful analytics.</h2>\n        <p class=\"lv-lead\">The detail is the point. Northwind keeps the tonal range calm so the numbers\n          are what stand out.</p>\n      </div>\n      <div class=\"lv-feats\">\n        <article class=\"lv-feat\">\n          <span class=\"lv-fi\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 19V5M4 19h16M8 15l3-4 3 2 4-6\"/></svg>\n          </span>\n          <h3 class=\"lv-card-title\">One tonal scale</h3>\n          <p class=\"lv-card-desc\">Every surface, border and caption is drawn from a single warm neutral\n            range, so nothing fights the data.</p>\n        </article>\n        <article class=\"lv-feat\">\n          <span class=\"lv-fi\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"3\"/><path d=\"M4 10h16M10 10v10\"/></svg>\n          </span>\n          <h3 class=\"lv-card-title\">Composable grids</h3>\n          <p class=\"lv-card-desc\">Drop metric cards, region tables and pricing tiers into an editorial\n            two- and three-column rhythm.</p>\n        </article>\n        <article class=\"lv-feat\">\n          <span class=\"lv-fi\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 8v4l3 2\"/></svg>\n          </span>\n          <h3 class=\"lv-card-title\">Built to review</h3>\n          <p class=\"lv-card-desc\">Share a board, collect comments and sign off &mdash; the review trail is\n            part of the document.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"lv-sec\" aria-labelledby=\"lvQuoteH\">\n    <div class=\"lv-wrap\">\n      <figure class=\"lv-quote\">\n        <blockquote>\n          <p id=\"lvQuoteH\">&ldquo;Northwind turned our Monday scramble into a fifteen-minute review.\n            The region view caught a dock bottleneck we'd argued about for a quarter.&rdquo;</p>\n        </blockquote>\n        <figcaption>\n          <span class=\"lv-avatar\" aria-hidden=\"true\">RM</span>\n          <span><b>Rhea Mancini</b><br><span class=\"lv-muted\">Head of Operations, Meridian Logistics</span></span>\n        </figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <section id=\"cta\" class=\"lv-sec\" aria-labelledby=\"lvCtaH\">\n    <div class=\"lv-wrap\">\n      <div class=\"lv-cta\">\n        <div class=\"lv-cta-wash\" aria-hidden=\"true\"></div>\n        <h2 id=\"lvCtaH\" class=\"lv-h2\">Your first board is waiting.</h2>\n        <p class=\"lv-lead lv-lead-center\">Open a workspace, describe what you need, and watch the regions\n          fall into place.</p>\n        <div class=\"lv-cta-row\">\n          <a class=\"lv-btn lv-btn-dark\" href=\"#\">Start building</a>\n          <a class=\"lv-btn lv-btn-outline\" href=\"#\">Book a walkthrough</a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <footer class=\"lv-foot\">\n    <div class=\"lv-wrap\">\n      <div class=\"lv-foot-top\">\n        <div class=\"lv-foot-brand\">\n          <span class=\"lv-mark\" aria-hidden=\"true\">N</span>\n          <span class=\"lv-word\">Northwind</span>\n          <p class=\"lv-muted\">Operations analytics on a warm page.</p>\n        </div>\n        <div class=\"lv-foot-cols\">\n          <div class=\"lv-foot-col\">\n            <h3>Product</h3>\n            <a href=\"#\">Templates</a><a href=\"#\">Boards</a><a href=\"#\">Regions</a><a href=\"#\">Pricing</a>\n          </div>\n          <div class=\"lv-foot-col\">\n            <h3>Company</h3>\n            <a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Customers</a><a href=\"#\">Contact</a>\n          </div>\n          <div class=\"lv-foot-col\">\n            <h3>Resources</h3>\n            <a href=\"#\">Docs</a><a href=\"#\">Guides</a><a href=\"#\">Changelog</a><a href=\"#\">Status</a>\n          </div>\n        </div>\n      </div>\n      <div class=\"lv-foot-bottom\">\n        <span>&copy; 2026 Northwind Analytics</span>\n        <span class=\"lv-foot-links\"><a href=\"#\">Privacy</a><a href=\"#\">Terms</a></span>\n      </div>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Lovable design language ═══════════════════\n   Warm parchment canvas, opacity-derived neutrals from #1c1c1c, humanist display\n   type with tight negative tracking, inset-shadow dark buttons, border-contained\n   cards, and a soft warm gradient wash behind the hero. Scoped to .own-lovable. */\n\n.own-lovable {\n  --cream: #f7f4ed;\n  --charcoal: #1c1c1c;\n  --off-white: #fcfbf8;\n  --muted: #5f5f5d;\n  --border: #eceae4;\n  --border-strong: rgba(28, 28, 28, .4);\n  --ink-83: rgba(28, 28, 28, .83);\n  --ink-40: rgba(28, 28, 28, .4);\n  --ink-04: rgba(28, 28, 28, .04);\n  --inset: rgba(255, 255, 255, .2) 0px .5px 0px 0px inset,\n           rgba(0, 0, 0, .2) 0px 0px 0px .5px inset,\n           rgba(0, 0, 0, .05) 0px 1px 2px 0px;\n  --focus: rgba(0, 0, 0, .1) 0px 4px 12px;\n  --ring: rgba(59, 130, 246, .5);\n  --display: 'Camera Plain Variable', ui-sans-serif, system-ui, sans-serif;\n  --gut: clamp(20px, 5cqi, 64px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--cream);\n  color: var(--charcoal);\n  font-family: var(--display);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n.own-lovable *,\n.own-lovable *::before,\n.own-lovable *::after { box-sizing: border-box; }\n.own-lovable :focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: 4px; }\n.own-lovable .lv-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.own-lovable .lv-muted { color: var(--muted); }\n.own-lovable .lv-wrap { max-width: 1200px; margin: 0 auto; padding: 0 var(--gut); }\n\n/* ── type ────────────────────────────────────────────────────────────────── */\n.own-lovable .lv-h1 { font-weight: 600; font-size: clamp(38px, 5cqi, 60px); line-height: 1.06; letter-spacing: -1.5px; }\n.own-lovable .lv-h2 { font-weight: 600; font-size: clamp(30px, 3.6cqi, 48px); line-height: 1.02; letter-spacing: -1.2px; }\n.own-lovable .lv-eyebrow { display: inline-block; font-size: 13px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); margin-bottom: 20px; }\n.own-lovable .lv-lead { color: var(--muted); font-size: 18px; line-height: 1.4; max-width: 54ch; }\n.own-lovable .lv-lead-center { margin: 16px auto 0; text-align: center; }\n.own-lovable .lv-sub { color: var(--ink-83); font-size: 18px; line-height: 1.4; max-width: 50ch; margin-top: 20px; }\n.own-lovable .lv-card-title { font-weight: 400; font-size: 20px; line-height: 1.25; }\n.own-lovable .lv-card-desc { color: var(--muted); font-size: 14px; line-height: 1.5; margin-top: 6px; }\n\n/* ── nav ─────────────────────────────────────────────────────────────────── */\n.own-lovable .lv-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 28px;\n  max-width: 1200px; margin: 18px auto 0; padding: 10px 14px 10px 20px;\n  border-radius: 9999px;\n  background: rgba(247, 244, 237, .82);\n  backdrop-filter: blur(10px);\n  border: 1px solid var(--border);\n}\n.own-lovable .lv-brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--charcoal); white-space: nowrap; }\n.own-lovable .lv-mark { width: 28px; height: 28px; border-radius: 8px; background: var(--charcoal); color: var(--off-white); display: grid; place-items: center; font-weight: 600; font-size: 15px; }\n.own-lovable .lv-word { font-weight: 600; font-size: 18px; letter-spacing: -.4px; }\n.own-lovable .lv-links { display: flex; align-items: center; gap: 26px; margin-left: 8px; }\n.own-lovable .lv-links a { color: var(--ink-83); text-decoration: none; font-size: 15px; }\n.own-lovable .lv-links a:hover { color: var(--charcoal); }\n.own-lovable .lv-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; }\n\n/* ── buttons ────────────────────────────────────────────────────────────── */\n.own-lovable .lv-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 38px; padding: 0 16px; border-radius: 6px; font-family: var(--display);\n  font-size: 15px; font-weight: 500; text-decoration: none; cursor: pointer;\n  border: 1px solid transparent; transition: opacity .15s, box-shadow .15s;\n}\n.own-lovable .lv-btn:active { opacity: .8; }\n.own-lovable .lv-btn:focus-visible { box-shadow: var(--focus); }\n.own-lovable .lv-btn-dark { background: var(--charcoal); color: var(--off-white); box-shadow: var(--inset); }\n.own-lovable .lv-btn-ghost { background: transparent; color: var(--charcoal); border-color: var(--border-strong); }\n.own-lovable .lv-btn-outline { background: var(--cream); color: var(--charcoal); border-color: var(--border-strong); }\n.own-lovable .lv-menu { display: none; width: 38px; height: 38px; align-items: center; justify-content: center; background: var(--cream); color: var(--charcoal); border: 1px solid var(--border); border-radius: 6px; cursor: pointer; }\n.own-lovable .lv-menu svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-lovable .lv-hero { position: relative; overflow: hidden; padding: clamp(48px, 8cqi, 96px) 0 64px; }\n.own-lovable .lv-wash {\n  position: absolute; inset: -20% -10% auto -10%; height: 620px; z-index: 0;\n  background:\n    radial-gradient(42% 58% at 22% 30%, rgba(255, 173, 121, .40), transparent 70%),\n    radial-gradient(40% 55% at 68% 18%, rgba(255, 128, 168, .34), transparent 70%),\n    radial-gradient(46% 60% at 52% 58%, rgba(120, 170, 255, .30), transparent 72%);\n  filter: blur(14px);\n  opacity: .8;\n  pointer-events: none;\n}\n.own-lovable .lv-hero-inner { position: relative; z-index: 1; max-width: 760px; margin: 0 auto; padding: 0 var(--gut); text-align: center; }\n\n/* chat input */\n.own-lovable .lv-chat {\n  margin: 30px auto 0; max-width: 680px; text-align: left;\n  background: var(--cream); border: 1px solid var(--border); border-radius: 16px;\n  padding: 16px; box-shadow: var(--focus);\n}\n.own-lovable .lv-chat textarea {\n  width: 100%; border: 0; background: transparent; resize: none; color: var(--charcoal);\n  font-family: var(--display); font-size: 16px; line-height: 1.5; min-height: 52px;\n}\n.own-lovable .lv-chat textarea::placeholder { color: var(--muted); }\n.own-lovable .lv-chat textarea:focus { outline: none; }\n.own-lovable .lv-chat-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 10px; }\n.own-lovable .lv-suggest { display: flex; flex-wrap: wrap; gap: 8px; }\n.own-lovable .lv-pill {\n  height: 32px; padding: 0 14px; border-radius: 9999px; cursor: pointer;\n  background: var(--cream); color: var(--ink-83); border: 1px solid var(--border);\n  font-family: var(--display); font-size: 13px; transition: background .15s;\n}\n.own-lovable .lv-pill:hover { background: var(--ink-04); }\n.own-lovable .lv-send {\n  flex: none; width: 40px; height: 40px; border-radius: 9999px; border: 0; cursor: pointer;\n  background: var(--charcoal); color: var(--off-white); box-shadow: var(--inset);\n  display: grid; place-items: center; transition: opacity .15s;\n}\n.own-lovable .lv-send:hover { opacity: .85; }\n.own-lovable .lv-send svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.own-lovable .lv-trust { text-align: center; color: var(--muted); font-size: 13px; margin-top: 18px; }\n\n/* ── sections ───────────────────────────────────────────────────────────── */\n.own-lovable .lv-sec { padding: clamp(56px, 8cqi, 128px) 0; }\n.own-lovable .lv-sec-tight { padding: clamp(40px, 5cqi, 72px) 0; }\n.own-lovable .lv-sec-head { max-width: 640px; margin: 0 auto 48px; text-align: center; }\n.own-lovable .lv-sec-head.lv-left { margin-left: 0; text-align: left; }\n.own-lovable .lv-sec-head .lv-lead { margin-top: 14px; }\n\n/* template gallery */\n.own-lovable .lv-gallery { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-lovable .lv-card {\n  display: block; text-decoration: none; color: inherit;\n  background: var(--cream); border: 1px solid var(--border); border-radius: 12px;\n  overflow: hidden; transition: border-color .2s, transform .2s;\n}\n.own-lovable .lv-card:hover { border-color: var(--ink-40); transform: translateY(-2px); }\n.own-lovable .lv-thumb { position: relative; height: 180px; border-bottom: 1px solid var(--border); display: grid; }\n.own-lovable .lv-thumb-label { position: absolute; left: 14px; bottom: 12px; font-size: 12px; font-weight: 600; color: var(--ink-83); }\n.own-lovable .lv-thumb-a { grid-template-columns: 1fr 1fr; gap: 8px; padding: 18px; background: linear-gradient(180deg, #fbf6ee, #f3ede1); }\n.own-lovable .lv-thumb-a .lv-tile { border: 1px solid var(--border); border-radius: 8px; background: var(--cream); }\n.own-lovable .lv-thumb-a .lv-tile:nth-child(2) { background: rgba(28,28,28,.06); }\n.own-lovable .lv-thumb-a .lv-tile:nth-child(4) { background: rgba(28,28,28,.1); }\n.own-lovable .lv-thumb-b { place-items: center; background: linear-gradient(180deg, #fbf6ee, #f6e9e2); }\n.own-lovable .lv-thumb-b .lv-ring { position: absolute; width: 120px; height: 120px; border: 1px solid var(--ink-40); border-radius: 50%; }\n.own-lovable .lv-thumb-b .lv-ring:nth-child(2) { width: 72px; height: 72px; border-color: var(--ink-83); }\n.own-lovable .lv-thumb-c { place-items: end center; padding: 22px; background: linear-gradient(180deg, #fbf6ee, #edf1f7); }\n.own-lovable .lv-bars { display: flex; align-items: flex-end; gap: 12px; height: 120px; }\n.own-lovable .lv-bars i { display: block; width: 16px; height: var(--h); background: var(--charcoal); border-radius: 4px 4px 0 0; opacity: .8; }\n.own-lovable .lv-bars i:nth-child(3) { opacity: 1; }\n.own-lovable .lv-card-body { padding: 18px 20px 22px; }\n.own-lovable .lv-cat { display: inline-block; margin-top: 12px; font-size: 12px; color: var(--muted); border: 1px solid var(--border); border-radius: 9999px; padding: 3px 10px; }\n\n/* stats */\n.own-lovable .lv-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); padding: 40px 0; }\n.own-lovable .lv-stat b { display: block; font-weight: 600; font-size: clamp(32px, 3.4cqi, 48px); letter-spacing: -1.2px; line-height: 1; }\n.own-lovable .lv-stat span { display: block; margin-top: 10px; color: var(--muted); font-size: 15px; }\n\n/* features */\n.own-lovable .lv-feats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-lovable .lv-feat { background: var(--cream); border: 1px solid var(--border); border-radius: 16px; padding: 28px; }\n.own-lovable .lv-fi { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--ink-04); border: 1px solid var(--border); margin-bottom: 20px; }\n.own-lovable .lv-fi svg { width: 22px; height: 22px; fill: none; stroke: var(--charcoal); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n\n/* quote */\n.own-lovable .lv-quote { max-width: 800px; margin: 0 auto; text-align: center; }\n.own-lovable .lv-quote blockquote p { font-weight: 480; font-size: clamp(24px, 3cqi, 36px); line-height: 1.24; letter-spacing: -.9px; }\n.own-lovable .lv-quote figcaption { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 28px; font-size: 15px; text-align: left; }\n.own-lovable .lv-avatar { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 9999px; background: var(--charcoal); color: var(--off-white); font-weight: 600; font-size: 14px; }\n\n/* cta */\n.own-lovable .lv-cta { position: relative; overflow: hidden; border: 1px solid var(--border); border-radius: 16px; padding: clamp(40px, 6cqi, 80px) 32px; text-align: center; background: var(--cream); }\n.own-lovable .lv-cta-wash { position: absolute; inset: -40% -10% auto -10%; height: 320px; background: radial-gradient(40% 60% at 30% 40%, rgba(255, 173, 121, .34), transparent 72%), radial-gradient(44% 60% at 72% 30%, rgba(120, 170, 255, .26), transparent 72%); filter: blur(16px); opacity: .8; pointer-events: none; }\n.own-lovable .lv-cta > * { position: relative; z-index: 1; }\n.own-lovable .lv-cta-row { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 28px; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-lovable .lv-foot { border-top: 1px solid var(--border); margin-top: clamp(40px, 5cqi, 80px); padding: 56px 0 32px; background: linear-gradient(180deg, var(--cream), #f1ece0); }\n.own-lovable .lv-foot-top { display: grid; grid-template-columns: 1.2fr 2fr; gap: 40px; }\n.own-lovable .lv-foot-brand .lv-mark { display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: var(--charcoal); color: var(--off-white); font-weight: 600; font-size: 15px; }\n.own-lovable .lv-foot-brand .lv-word { font-weight: 600; font-size: 18px; margin-left: 8px; }\n.own-lovable .lv-foot-brand p { margin-top: 12px; font-size: 14px; max-width: 30ch; }\n.own-lovable .lv-foot-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-lovable .lv-foot-col h3 { font-weight: 600; font-size: 14px; margin-bottom: 14px; }\n.own-lovable .lv-foot-col a { display: block; color: var(--muted); text-decoration: none; font-size: 14px; margin-bottom: 9px; }\n.own-lovable .lv-foot-col a:hover { color: var(--charcoal); text-decoration: underline; }\n.own-lovable .lv-foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 44px; padding-top: 20px; border-top: 1px solid var(--border); color: var(--muted); font-size: 13px; }\n.own-lovable .lv-foot-links { display: flex; gap: 20px; }\n.own-lovable .lv-foot-links a { color: var(--muted); text-decoration: none; }\n.own-lovable .lv-foot-links a:hover { color: var(--charcoal); text-decoration: underline; }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-lovable .lv-links { display: none; }\n  .own-lovable .lv-gallery { grid-template-columns: repeat(2, 1fr); }\n  .own-lovable .lv-stats { grid-template-columns: repeat(2, 1fr); row-gap: 28px; }\n  .own-lovable .lv-feats { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-lovable .lv-nav { top: 10px; margin: 10px 12px 0; border-radius: 16px; }\n  .own-lovable .lv-links { display: none; }\n  .own-lovable .lv-menu { display: inline-flex; }\n  .own-lovable .lv-gallery { grid-template-columns: 1fr; }\n  .own-lovable .lv-chat-foot { flex-direction: column; align-items: stretch; }\n  .own-lovable .lv-send { align-self: flex-end; }\n  .own-lovable .lv-foot-top { grid-template-columns: 1fr; }\n  .own-lovable .lv-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-lovable .lv-stats { grid-template-columns: 1fr; }\n  .own-lovable .lv-foot-cols { grid-template-columns: 1fr; }\n  .own-lovable .lv-nav { padding: 8px 10px 8px 14px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-lovable *, .own-lovable *::before, .own-lovable *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Lovable own-layout behaviour ══════════════════════════════
   Registers window.OWN_LAYOUTS['lovable'].init(root). The only dynamic bit is
   the prompt composer: suggestion pills fill the textarea and the textarea
   auto-grows. Returns a cleanup that removes every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['lovable'] = {
    init: function (root) {
      var ta = root.querySelector('#lvPrompt');
      var chat = root.querySelector('[data-chat]');
      var suggestions = Array.prototype.slice.call(root.querySelectorAll('[data-suggest]'));
      var menu = root.querySelector('[data-menu]');
      var nav = root.querySelector('.lv-links');

      function grow() {
        if (!ta) return;
        ta.style.height = 'auto';
        ta.style.height = Math.min(140, ta.scrollHeight) + 'px';
      }
      function onSuggest(e) {
        if (!ta) return;
        ta.value = e.currentTarget.textContent.trim();
        grow();
        ta.focus();
      }
      function onSubmit(e) {
        e.preventDefault();
        if (ta) grow();
      }
      function onMenu() {
        if (!nav) return;
        var open = nav.getAttribute('data-open') === '1';
        nav.setAttribute('data-open', open ? '0' : '1');
        nav.style.display = open ? '' : 'flex';
        nav.style.position = 'absolute';
        nav.style.top = '64px';
        nav.style.left = '12px';
        nav.style.right = '12px';
        nav.style.margin = '0';
        nav.style.flexDirection = 'column';
        nav.style.alignItems = 'flex-start';
        nav.style.gap = '4px';
        nav.style.padding = '12px';
        nav.style.background = 'var(--cream)';
        nav.style.border = '1px solid var(--border)';
        nav.style.borderRadius = '12px';
        nav.style.zIndex = '40';
      }

      if (ta) ta.addEventListener('input', grow);
      suggestions.forEach(function (b) { b.addEventListener('click', onSuggest); });
      if (chat) chat.addEventListener('submit', onSubmit);
      if (menu) menu.addEventListener('click', onMenu);
      grow();

      return function cleanup() {
        if (ta) ta.removeEventListener('input', grow);
        suggestions.forEach(function (b) { b.removeEventListener('click', onSuggest); });
        if (chat) chat.removeEventListener('submit', onSubmit);
        if (menu) menu.removeEventListener('click', onMenu);
        if (nav) { nav.removeAttribute('style'); nav.removeAttribute('data-open'); }
        if (ta) ta.style.height = '';
      };
    }
  };
})();
